"""Isolated offline worker. Input paths are generated by the parent, never client supplied."""
from __future__ import annotations

from dataclasses import asdict
import hashlib
from importlib import metadata
import json
import math
from pathlib import Path
import re
import sys

COMMIT = '69d42e38979f381fe531ae547fcc49b8ad58ef15'
STOPWORDS_SHA256 = 'f6d005956f407dbc6ea32e5ff0c7e8e6f71488d3239b9023efdc7fc139d6375b'
NAMESPACE = 'https://example.org/oe-demo/'
SCORES = ('vocabulary_coverage', 'vocabulary_utilisation', 'strict_fitness',
          'approximate_fitness', 'structural_fitness')


class Unsupported(ValueError):
    pass


def disable_network_and_children():
    def audit(event, args):
        if event in {'socket.connect', 'socket.getaddrinfo', 'socket.sendto', 'socket.sendmsg',
                     'subprocess.Popen', 'os.system', 'os.exec', 'os.posix_spawn'}:
            raise PermissionError('Offline assessment prohibits networking and child processes')
    sys.addaudithook(audit)


def inspect_questions(questions):
    from rdflib import URIRef, Variable
    from rdflib.namespace import RDF
    from rdflib.plugins.sparql import prepareQuery
    from rdflib.plugins.sparql.parserutils import CompValue
    from ontocheck.query_fitness import load_query_patterns
    from ontocheck.task_based_metric import _extract_terms_from_sparql
    if not isinstance(questions, list) or not 0 < len(questions) <= 50:
        raise Unsupported('Provide 1–50 development questions; empty vocabulary is undefined.')
    strings = []
    records = []
    ids = set()
    roles = {}
    for question in questions:
        if not isinstance(question, dict):
            raise Unsupported('Every question must be an object with id and sparql_query.')
        qid = question.get('id')
        if not isinstance(qid, str) or not qid or qid in ids:
            raise Unsupported('Question IDs must be nonempty and unique.')
        ids.add(qid)
        query = question.get('sparql_query')
        if not isinstance(query, str) or not query.strip() or len(query) > 16_000:
            raise Unsupported(f'{qid}: a bounded SPARQL query is required; questions cannot be skipped.')
        try:
            parsed = prepareQuery(query)
        except Exception as exc:
            raise Unsupported(f'{qid}: unsupported or malformed SPARQL ({type(exc).__name__}).') from exc
        # Prefix-only task terms make the upstream regex vocabulary denominator inspectable.
        body = re.sub(r'(?im)\bPREFIX\s+[\w-]*:\s*<[^>]*>', '', query)
        if re.search(r'<[^>]+>', body):
            raise Unsupported(f'{qid}: use local ASK/SELECT with explicit ex: terms; full-IRI terms and remote clauses are unsupported.')
        if not re.search(r'(?i)PREFIX\s+ex:\s*<' + re.escape(NAMESPACE) + r'>', query):
            raise Unsupported(f'{qid}: ex: must bind the frozen demo namespace.')
        if not re.search(r'\bex:[A-Za-z_][\w-]*', body):
            raise Unsupported(f'{qid}: no supported domain vocabulary was found.')
        # Upstream fitness flattens every BGP and silently drops path predicates.
        # Admit only the algebra whose required terms and edges it preserves.
        domain_terms = set()
        types = {}

        def inspect(node):
            if not isinstance(node, CompValue):
                return
            if node.name not in {'SelectQuery', 'AskQuery', 'Project', 'Distinct', 'BGP'}:
                raise Unsupported(f'{qid}: unsupported assessment algebra: {node.name}.')
            if 'datasetClause' in node and node['datasetClause']:
                raise Unsupported(f'{qid}: dataset clauses are unsupported.')
            if node.name == 'BGP':
                for subject, predicate, obj in node['triples']:
                    if not isinstance(predicate, URIRef) or not isinstance(subject, (URIRef, Variable)):
                        raise Unsupported(f'{qid}: paths, variable predicates and blank nodes are unsupported.')
                    if predicate == RDF.type:
                        if not isinstance(obj, URIRef):
                            raise Unsupported(f'{qid}: class requirements must be named IRIs.')
                        types.setdefault(subject, set()).add(obj)
                        if len(types[subject]) > 1:
                            raise Unsupported(f'{qid}: multiple types for one query node are not preserved upstream.')
                        roles.setdefault(str(obj), set()).add('class')
                    else:
                        roles.setdefault(str(predicate), set()).add('property')
                        if isinstance(obj, URIRef):
                            roles.setdefault(str(obj), set()).add('individual')
                    if isinstance(subject, URIRef):
                        roles.setdefault(str(subject), set()).add('individual')
                    for term in (subject, predicate, obj):
                        if isinstance(term, URIRef) and term != RDF.type:
                            if not str(term).startswith(NAMESPACE):
                                raise Unsupported(f'{qid}: query terms must use the frozen domain namespace.')
                            domain_terms.add(str(term)[len(NAMESPACE):])
            for value in node.values():
                if isinstance(value, CompValue):
                    inspect(value)

        inspect(parsed.algebra)
        if domain_terms != _extract_terms_from_sparql(query, ['ex']):
            raise Unsupported(f'{qid}: parsed task terms differ from upstream vocabulary extraction; comments, literals or aliases cannot change the denominator.')
        # Fitness must evaluate exactly the SPARQL workload also used by vocabulary coverage.
        # Client graph_query cannot silently replace this question's query semantics.
        record = {'qid': qid, 'question': question.get('question', ''), 'sparql_query': query}
        if len(load_query_patterns([record])) != 1:
            raise Unsupported(f'{qid}: upstream fitness skipped the question.')
        strings.append(query)
        records.append(record)
    return strings, records, roles


def inspect_graph(path):
    from rdflib import Graph, URIRef
    from rdflib.namespace import OWL, RDF, RDFS
    graph = Graph().parse(path, format='turtle')
    if list(graph.triples((None, OWL.imports, None))):
        raise Unsupported('Remote or unresolved owl:imports are unsupported; materialize reviewed local imports first.')
    terms = set()
    for rdf_type in (OWL.Class, RDFS.Class, OWL.ObjectProperty, OWL.DatatypeProperty, RDF.Property):
        terms.update(s for s in graph.subjects(RDF.type, rdf_type) if isinstance(s, URIRef))
    for predicate in (RDFS.label, RDFS.domain, RDFS.range):
        terms.update(s for s in graph.subjects(predicate, None) if isinstance(s, URIRef))
    names = {}
    for term in terms:
        iri = str(term)
        if NAMESPACE in iri and not iri.startswith(NAMESPACE):
            raise Unsupported('Embedded namespace fragments cannot define domain membership.')
        if iri.startswith(('http://www.w3.org/', 'https://www.w3.org/')):
            continue
        local = re.split(r'[/#]', iri)[-1]
        names.setdefault(local, set()).add(iri)
    collisions = {name: sorted(iris) for name, iris in names.items() if len(iris) > 1}
    if collisions:
        raise Unsupported('Namespace local-name collision makes vocabulary overlap ambiguous: ' + json.dumps(collisions))
    return graph


def inspect_mappings(mappings, records, roles, graph):
    """Reject silent upstream mapping drops and term-kind confusion, retaining absence."""
    from rdflib import URIRef
    from ontocheck.context_weighting import EntityUniverse
    from ontocheck.query_fitness import load_query_patterns
    universe = EntityUniverse(graph)
    requirements = {term.key for pattern in load_query_patterns(records) for term in pattern.concepts}
    result = []
    for mapping in mappings:
        requirement, target = mapping['requirement_iri'], URIRef(mapping['ontology_iri'])
        if requirement not in requirements:
            raise Unsupported(f'Mapping requirement is not evaluated by the frozen questions: {requirement}')
        required_roles = roles.get(requirement, set())
        if len(required_roles) != 1:
            raise Unsupported(f'Mapping requirement has ambiguous term kinds: {requirement}')
        target_roles = set()
        if target in universe.classes:
            target_roles.add('class')
        if target in universe.properties or (None, target, None) in graph:
            target_roles.add('property')
        if target in universe.individuals:
            target_roles.add('individual')
        if target_roles and target_roles != required_roles:
            raise Unsupported(f'Mapping target has incompatible term kind: {target}')
        result.append({'requirement_iri': requirement, 'ontology_iri': str(target),
                       'requirement_kind': next(iter(required_roles)), 'target_present': bool(target_roles)})
    return result


def measure(path, queries, records, mappings):
    from ontocheck import conceptual_fitness, structural_fitness, task_based_metric_v_0_0_1
    from ontocheck.task_based_metric import _get_ontology_terms, _extract_terms_from_sparql
    vocabulary = task_based_metric_v_0_0_1(
        path, queries, domain_prefixes=['ex'], domain_ns_fragments=[NAMESPACE], auto_derive_fragments=False,
    )
    conceptual = asdict(conceptual_fitness(path, records, mappings=mappings, authorize_prefix_mapping=False))
    structural = asdict(structural_fitness(
        path, records, mappings=mappings, authorize_prefix_mapping=False, weighting='canonical',
        lam=math.log(2), max_hops=8,
    ))
    if (conceptual['detail']['queries'] != len(records)
            or len(structural['detail']['per_query']) != len(records)):
        raise Unsupported('Upstream fitness silently skipped a required development question.')
    ontology_terms, _ = _get_ontology_terms([path], [NAMESPACE])
    task_terms = set().union(*(_extract_terms_from_sparql(query, ['ex']) for query in queries))
    return {'vocabulary': vocabulary, 'conceptual': conceptual, 'structural': structural,
            'term_sets': {'task': sorted(task_terms), 'ontology': sorted(ontology_terms),
                          'intersection': sorted(task_terms & ontology_terms)}}


def normalized(raw):
    vocabulary = raw['vocabulary']
    return {
        'vocabulary_coverage': vocabulary['recall'] if vocabulary['T_a_count'] else None,
        'vocabulary_utilisation': vocabulary['precision'] if vocabulary['T_o_count'] else None,
        'strict_fitness': raw['conceptual']['score'],
        'approximate_fitness': raw['conceptual']['detail']['aligned_score'],
        'structural_fitness': raw['structural']['score'],
    }


def run(payload, folder):
    import nltk
    resource_root = Path(payload['nltk_data_dir'])
    if hashlib.sha256((resource_root / 'corpora/stopwords/english').read_bytes()).hexdigest() != STOPWORDS_SHA256:
        raise RuntimeError('The pinned English stopwords resource is missing or has changed')
    # NLTK_DATA alone still appends the user's home directories. Restrict the actual
    # search list before the pinned OntoCheck import's eager stopwords lookup.
    nltk.data.path[:] = [str(resource_root)]
    direct = json.loads(metadata.distribution('ontocheck').read_text('direct_url.json') or '{}')
    if direct.get('vcs_info', {}).get('commit_id') != COMMIT:
        raise RuntimeError('OntoCheck must be installed from the exact reviewed Git commit.')
    query_strings, records, roles = inspect_questions(payload['questions'])
    mappings = payload.get('mappings', [])
    mapping_dict = {item['requirement_iri']: item['ontology_iri'] for item in mappings}
    mapping_hash = hashlib.sha256(json.dumps(
        mappings, sort_keys=True, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode()).hexdigest()
    report = {'status': 'completed', 'raw': {}, 'deltas': {}, 'denominators': {},
              'missing_reasons': {}, 'limitations': [], 'mappings': mappings,
              'mappings_sha256': mapping_hash, 'mapping_diagnostics': {}}
    report['engine'] = {
        'python': sys.version.split()[0],
        'resources': {'nltk_english_stopwords_sha256': STOPWORDS_SHA256},
        'packages': {name: metadata.version(name) for name in ('ontocheck', 'rdflib', 'networkx', 'nltk')},
        'configuration': {'domain_prefixes': ['ex'], 'domain_ns_fragments': [NAMESPACE],
                          'authorize_prefix_mapping': False, 'mappings': mapping_dict,
                          'mappings_sha256': mapping_hash, 'weighting': 'canonical',
                          'max_hops': 8, 'lam': math.log(2)},
    }
    for label, content in [('candidate', payload['ontology_ttl']), ('base', payload.get('base_ttl', ''))]:
        if label == 'base' and not content:
            continue
        path = folder / f'{label}.ttl'
        path.write_text(content, encoding='utf-8')
        graph = inspect_graph(path)
        report['mapping_diagnostics'][label] = inspect_mappings(mappings, records, roles, graph)
        raw = measure(path, query_strings, records, mapping_dict)
        raw['ontology_sha256'] = hashlib.sha256(content.encode()).hexdigest()
        raw['mappings_sha256'] = mapping_hash
        report['raw'][label] = raw
        report['denominators'][label] = {
            'task_terms': raw['vocabulary']['T_a_count'], 'ontology_terms': raw['vocabulary']['T_o_count'],
            'overlap': raw['vocabulary']['intersection'], 'questions': len(records),
        }
    candidate = report['raw']['candidate']
    report.update(normalized(candidate))
    if report['structural_fitness'] is None:
        report['missing_reasons']['structural_fitness'] = 'No evaluable task edges; structural fitness is undefined.'
    if report['vocabulary_coverage'] is None:
        report['missing_reasons']['vocabulary_coverage'] = 'Task vocabulary denominator is empty.'
    if report['vocabulary_utilisation'] is None:
        report['missing_reasons']['vocabulary_utilisation'] = 'Ontology vocabulary denominator is empty.'
    if not candidate['vocabulary']['T_o_count'] or not candidate['vocabulary']['T_a_count']:
        report['status'] = 'unsupported'
        report['limitations'].append('Vocabulary denominator is empty; undefined ratios remain null.')
    if 'base' in report['raw']:
        base_scores = normalized(report['raw']['base'])
        report['deltas'] = {key: report[key] - base_scores[key]
                            if report[key] is not None and base_scores[key] is not None else None for key in SCORES}
    report['questions_sha256'] = hashlib.sha256(
        json.dumps(payload['questions'], sort_keys=True, separators=(',', ':')).encode()).hexdigest()
    return report


def main():
    disable_network_and_children()
    request = Path(sys.argv[1])
    try:
        payload = json.loads(request.read_text(encoding='utf-8'))
        report = run(payload, request.parent)
    except Unsupported as exc:
        report = {'status': 'unsupported', 'limitations': [str(exc)]}
    except Exception as exc:
        report = {'status': 'error', 'limitations': [f'{type(exc).__name__}: {str(exc)[:1000]}']}
    print(json.dumps(report, default=lambda obj: sorted(obj) if isinstance(obj, set) else str(obj)))


if __name__ == '__main__':
    main()
